{'name': 'Scenario', 'cron': '0 6-8 * * *', 'period': 2000, 'code': "phase := false
accumulated_on_time := 0
prev_light_state := (#Light).switch_switch
irrigator_count := 0
prev_irrigator_state := (#Irrigator).switch_switch
if ((#Clock).clock_hour == 9) {
    break
}
if (phase == false) {
    phase = true
} else {
    light_state = (#Light).switch_switch
    if (light_state == 'on') {
        accumulated_on_time = accumulated_on_time + 2000
    }
    prev_light_state = light_state
    irrigator_state = (#Irrigator).switch_switch
    if ((prev_irrigator_state == 'off') and (irrigator_state == 'on')) {
        irrigator_count = irrigator_count + 1
    }
    prev_irrigator_state = irrigator_state
    if ((accumulated_on_time >= 600000) and (irrigator_count >= 3)) {
        (#Speaker).speaker_speak('관수 완료되었습니다')
        break
    }
}"}

