{'name': 'Scenario', 'cron': '0 22 * * *', 'period': 100, 'code': "phase := 0
door_count := 0
door_open_time := 0
prev_door_state := 'closed'
if ((#Clock).clock_hour == 23) {
    break
}
if (phase == 0) {
    if (((#Lower #Window).windowControl_window == 'open') and ((#Even #Light).switch_switch == 'on')) {
        (#Siren).sirenMode_setSirenMode('siren')
        (#Clock).clock_delay(5000)
        (#Blind).blind_close()
        phase = 1
    } else {
        break
    }
} else if (phase == 1) {
    door_state := (#Odd #DoorLock).doorControl_door
    if ((prev_door_state == 'open') and (door_state == 'closed')) {
        door_count = door_count + 1
    }
    prev_door_state = door_state
    if (door_count >= 2) {
        (#Curtain).curtain_close()
        phase = 2
    }
} else if (phase == 2) {
    door_state := (#Odd #DoorLock).doorControl_door
    if ((prev_door_state == 'closed') and (door_state == 'open')) {
        door_open_time = door_open_time + 100
    }
    if ((prev_door_state == 'open') and (door_state == 'closed')) {
        door_count = door_count - 1
    }
    prev_door_state = door_state
    if (door_count <= 0) {
        (#Alarm).alarm_strobe()
        (#Clock).clock_delay(door_open_time)
        (#Alarm).alarm_off()
        break
    }
}"}

{'name': 'Scenario', 'cron': '0 9 * * 1-5', 'period': 100, 'code': "phase := 0
if ((#Clock).clock_weekday == 'saturday') or ((#Clock).clock_weekday == 'sunday') {
    break
}
if (phase == 0) {
    if (((#Window).windowControl_window == 'closed') and ((#CO2Sensor).carbonDioxideMeasurement_co2Concentration >= 1000) and ((#TemperatureSensor).temperatureMeasurement_temperature >= 30)) {
        (#Clock).clock_delay(5000)
        (#Window).windowControl_open()
        if ((#Fan).switch_switch == 'off') {
            (#Fan).switch_on()
        }
        phase = 1
    }
} else {
    continuous_time := 0
    if ((#DustSensor).dustSensor_pm25 >= 50) {
        continuous_time = continuous_time + 100
    } else {
        continuous_time = 0
    }
    if (continuous_time >= 60000) {
        (#Window).windowControl_close()
        (#Fan).switch_off()
        if ((#HumiditySensor).relativeHumidityMeasurement_humidity <= 40) {
            (#Humidifier).irrigatorOperatingState_startWatering()
        }
        if (((#SoilMoistureSensor).soilMoistureMeasurement_soilMoisture <= 25) and ((#Irrigator).switch_switch == 'off')) {
            (#Irrigator).irrigatorOperatingState_startWatering()
        }
        break
    }
}"}

